await (async (page) => { await page.waitForTimeout(400); const r = await page.evaluate(async () => { const names = ['denji','power','aki','makima','kobeni','himeno','beam','reze','katana','quanxi']; const out = {}; for (const n of names){ const res = await fetch('assets/sprites/'+n+'.png', {method:'HEAD'}); out[n]=res.status; } return out; }); return r; })(page);
